2099	        }
2100	        // Remove from the runnable queue at the next deterministic drain. This
2101	        // is safe even if an asynchronous exec reconnect races a live
2102	        // tentative_pop: the handler never reaches the run queue's mutation
2103	        // guard and cannot poison the scheduler mutex.
2104	        self.deschedule_or_defer(*dtid);
2105	        // Remove from all non-runnable pools:
2106	        self.remove_blocking_entries(dtid);
2107	        self.remove_physical_thread(dtid, mm);
2108	        self.real_timers.retire_task(*detpid, *dtid);
2109	        self.retire_parked_requests(*dtid);
2110	
2111	        let _ = self.priorities.remove(dtid);
2112	        match self.next_turns.remove(dtid) {
2113	            None => {
2114	                trace!(
2115	                    "logically_kill_thread: thread already removed from scheduler: {}",
2116	                    &dtid
2117	                );
2118	            }
2119	            Some(nextturn) => {
2120	                info!(
2121	                    "logically_kill: Scheduler removing all knowledge of [det]tid {} in pid {}..",
2122	                    dtid, detpid
2123	                );
