4819	    /// Atomically classify a same-raw-TID exec handoff and record its fresh
4820	    /// admission. The scheduler mutex serializes this method with `step2`, so a
4821	    /// drain can never observe only one half of the handoff.
4822	    fn replace_retired_run_queue_incarnation(&mut self, dtid: DetTid, intent: AdmitIntent) {
4823	        let disposition = self
4824	            .pending_run_queue_removals
4825	            .get_mut(&dtid)
4826	            .unwrap_or_else(|| {
4827	                panic!(
4828	                    "exec replacement {:?} has no retired run-queue incarnation",
4829	                    dtid
4830	                )
4831	            });
4832	        assert_eq!(
4833	            *disposition,
4834	            RemovalDisposition::Retire,
4835	            "exec replacement {:?} was classified more than once",
4836	            dtid
4837	        );
4838	        *disposition = RemovalDisposition::ReplaceThenAdmit;
4839	        assert!(
4840	            self.pending_run_queue_admissions
4841	                .insert(dtid, intent)
4842	                .is_none(),
4843	            "exec replacement {:?} already had a pending admission",
4844	            dtid
4845	        );
4846	    }
