4848	    /// Resolve an [`AdmitIntent`] to a concrete [`AdmitSide`], consuming the
4849	    /// post-fork PRNG draw for `RunsPostFork::Random`.
4850	    ///
4851	    /// Called at the drain rather than in the handler, so the draw is never
4852	    /// consumed in host *RPC arrival* order, and the draws taken within one
4853	    /// drain follow canonical `DetTid` order. This function only canonicalizes
4854	    /// draws within a fixed drain; each admission site must separately bind its
4855	    /// drain membership to deterministic scheduler state. See
4856	    /// [`Scheduler::admit_to_run_queue`] for the causal and explicit barriers
4857	    /// that provide that binding for all current production sites.
4858	    fn resolve_admit_intent(&mut self, intent: AdmitIntent) -> AdmitSide {
4859	        match intent {
4860	            AdmitIntent::Fixed(side) => side,
4861	            AdmitIntent::PostFork(mode) => {
4862	                if self.child_runs_first_post_fork(mode) {
4863	                    AdmitSide::Front
4864	                } else {
4865	                    AdmitSide::Back
4866	                }
4867	            }
4868	        }
4869	    }
