4871	    /// Record an intent to remove `dtid` from the run queue, applied by the
4872	    /// daemon at the next deterministic drain point ([`step2`](Self::step2_drain_prefix)).
4873	    ///
4874	    /// The mirror of [`Scheduler::admit_to_run_queue`] for the removal side, and
4875	    /// deferred for the same reason: a global-request handler
4876	    /// (`reconnect_after_exec` -> `logically_kill_thread`) runs on a backend
4877	    /// worker and may hold the lock inside the daemon's tentative-pop window,
4878	    /// where `RunQueue::remove_tid`'s `tentative_selection.is_none()` assert
4879	    /// would trip and poison the scheduler mutex. Recording the removal and
4880	    /// applying it at `step2` (window closed, guard holds) avoids that. The
4881	    /// caller has already made the thread logically dead (cleared `next_turns`,
4882	    /// resolved its request to `ThreadExited`), so leaving its stale run-queue
4883	    /// entry in place until the drain is inert: the daemon skips it for any
4884	    /// intervening turn (`step3`'s pick is validated against `next_turns`) and
4885	    /// `are_all_quiesced` filters it out. On ptrace the drain runs at the next
4886	    /// `step2`, before that turn's `step3` selection, so the removal is
4887	    /// observationally immediate — the dead thread is never selected.
4888	    fn deschedule_or_defer(&mut self, dtid: DetTid) {
4889	        // A later logical death of a not-yet-drained exec replacement must
4890	        // override `ReplaceThenAdmit`: `remove_blocking_entries` clears its
4891	        // admission and this `Retire` disposition prevents resurrection.
4892	        self.pending_run_queue_removals
4893	            .insert(dtid, RemovalDisposition::Retire);
4894	    }
