4896	    /// Apply queued cross-task signal notifications at the deterministic
4897	    /// run-queue mutation point. Re-check the request because a target may have
4898	    /// exited or completed its wait before this drain.
4899	    fn drain_pending_cross_task_signals(&mut self) {
4900	        let pending = std::mem::take(&mut self.pending_cross_task_signals);
4901	        for (dettid, mut signals) in pending {
4902	            match self.waitid_signal_request(dettid) {
4903	                Some(WaitidSignalRequest::Parked) => {
4904	                    // Decide run-queue residency HERE, by asking the queue, and
4905	                    // never by inferring it from which resource the thread
4906	                    // holds. A thread can hold either park request while already
4907	                    // queued: `wake_child_waiters` re-admits a waiter without
4908	                    // clearing its `WaitChild` request, and `step6_reenqueue`
4909	                    // pushes a completed turn back before the guest issues its
4910	                    // next request. `force_unblock_thread` ends in
4911	                    // `runqueue_push_*`, so pushing an already-queued thread
4912	                    // trips the run-queue invariant under `debug_assertions`
4913	                    // and, worse, SILENTLY double-enqueues in release — one
4914	                    // thread selected twice. This mirrors `wake_signaled_guest`,
4915	                    // which likewise consults `thread_status` before removing.
4916	                    if self.run_queue.contains_tid(dettid) {
4917	                        let removed = self.run_queue.remove_tid(dettid);
4918	                        debug_assert!(
4919	                            removed,
4920	                            "run_queue.contains_tid disagreed with remove_tid for {dettid}"
4921	                        );
4922	                    }
4923	                    signals.sort_by_key(SigWrapper::raw);
4924	                    signals.dedup();
4925	                    let mut resources = Resources::new(dettid);
4926	                    resources.insert(ResourceID::WaitidSignals(signals), Permission::W);
4927	                    self.force_unblock_thread(dettid, resources);
4928	                }
4929	                Some(WaitidSignalRequest::Pending(existing)) => {
4930	                    signals.extend(existing);
4931	                    signals.sort_by_key(SigWrapper::raw);
4932	                    signals.dedup();
4933	                    // One resource, always. `step4_resource_block` and
4934	                    // `blocking_request_is_ready` both assert a request carries
4935	                    // exactly one, so this must replace the request rather than
4936	                    // add to it. Only a request whose sole resource is already
4937	                    // `WaitidSignals` reaches here, so nothing is discarded.
4938	                    let mut resources = Resources::new(dettid);
4939	                    resources.insert(ResourceID::WaitidSignals(signals), Permission::W);
4940	                    let Some(next_turn) = self.next_turns.get_mut(&dettid) else {
4941	                        continue;
4942	                    };
4943	                    next_turn.req = Ivar::full(Ok(resources));
4944	                }
4945	                None => {
4946	                    let Some(existing) = self.restartable_internal_io_signals(dettid) else {
4947	                        continue;
4948	                    };
4949	                    // ERESTARTSYS is the existing contract by which the kernel
4950	                    // decides whether this physically pending signal is
4951	                    // blocked, ignored, restarts the syscall, or interrupts it
4952	                    // for a handler. Replace the polling request rather than
4953	                    // adding a second resource; step4 accepts exactly one.
4954	                    if self.run_queue.contains_tid(dettid) {
4955	                        let removed = self.run_queue.remove_tid(dettid);
4956	                        debug_assert!(
4957	                            removed,
4958	                            "run_queue.contains_tid disagreed with remove_tid for {dettid}"
4959	                        );
4960	                    }
4961	                    signals.extend(existing);
4962	                    signals.sort_by_key(SigWrapper::raw);
4963	                    signals.dedup();
4964	                    if signals.is_empty() {
4965	                        continue;
4966	                    }
4967	                    let mut resources = Resources::new(dettid);
4968	                    // `WaitidSignals` is already the scheduler's one-resource
4969	                    // representation for a complete signal identity set. The
4970	                    // ERESTARTSYS marker distinguishes this write wakeup from a
4971	                    // waitid request and survives later notification batches.
4972	                    resources.insert(ResourceID::WaitidSignals(signals), Permission::W);
4973	                    resources.set_signal_interrupt_errno(Errno::ERESTARTSYS);
4974	                    self.force_unblock_thread(dettid, resources);
4975	                }
4976	            }
4977	        }
4978	    }
