4980	    /// Drain removals deferred by [`Scheduler::deschedule_or_defer`] at the same
4981	    /// deterministic `step2` point as admissions, and *before* them, so a thread
4982	    /// killed while an admission was still buffered is not re-enqueued. The
4983	    /// window is closed here (`tentative_selection` is `None`), so
4984	    /// `remove_tid`'s guard holds. The `BTreeMap` makes removal order canonical;
4985	    /// each disposition determines whether a same-raw-TID admission is stale or
4986	    /// is the explicitly paired exec replacement.
4987	    fn drain_pending_run_queue_removals(&mut self) {
4988	        if self.pending_run_queue_removals.is_empty() {
4989	            return;
4990	        }
4991	        let pending = std::mem::take(&mut self.pending_run_queue_removals);
4992	        for (dtid, disposition) in pending {
4993	            match disposition {
4994	                RemovalDisposition::Retire => {
4995	                    // Ordinary logical death cancels a buffered admission for
4996	                    // the same thread incarnation.
4997	                    self.pending_run_queue_admissions.remove(&dtid);
4998	                }
4999	                RemovalDisposition::ReplaceThenAdmit => {
5000	                    assert!(
5001	                        self.next_turns.contains_key(&dtid),
5002	                        "exec replacement {:?} lost its scheduler registration",
5003	                        dtid
5004	                    );
5005	                    assert!(
5006	                        self.pending_run_queue_admissions.contains_key(&dtid),
5007	                        "exec replacement {:?} lost its paired admission",
5008	                        dtid
5009	                    );
5010	                    assert!(
5011	                        !self.thread_is_logically_killed(dtid),
5012	                        "logically dead exec replacement {:?} reached the drain",
5013	                        dtid
5014	                    );
5015	                }
5016	            }
5017	            // Always remove the old physical queue slot before a replacement
5018	            // admission is applied. This prevents the new image from inheriting
5019	            // the destroyed leader's round-robin position.
5020	            let _ = self.run_queue.remove_tid(dtid);
5021	        }
5022	    }
