5040	    /// Drain admissions deferred by [`Scheduler::admit_to_run_queue`] into the
5041	    /// run queue at a single deterministic point: the very start of `step2`,
5042	    /// before `step3_peek` opens a tentative window (so `tentative_selection` is
5043	    /// guaranteed `None` here). Draining a `BTreeMap` visits `DetTid`s in sorted
5044	    /// order, so the resulting run-queue state is a pure function of the
5045	    /// deterministic schedule rather than of RPC/lock-acquisition timing.
5046	    fn drain_pending_run_queue_admissions(&mut self) {
5047	        if self.pending_run_queue_admissions.is_empty() {
5048	            return;
5049	        }
5050	        let pending = std::mem::take(&mut self.pending_run_queue_admissions);
5051	        // `pending` is a `BTreeMap`, so iteration visits `DetTid`s in sorted
5052	        // order. Resolving each intent here (rather than at the racing handler)
5053	        // means any `RunsPostFork::Random` PRNG draw is consumed in this
5054	        // canonical order, so both the admission order *and* the chosen side are
5055	        // pure functions of deterministic state.
5056	        for (dtid, intent) in pending {
5057	            // A thread retired (exec/kill) between record and drain is skipped.
5058	            // `remove_blocking_entries` also clears the buffer on teardown, so
5059	            // this guard is defensive against any teardown path that does not.
5060	            if !self.next_turns.contains_key(&dtid) {
5061	                trace!(
5062	                    "[step2] skipping deferred admission of retired thread {:?}",
5063	                    dtid
5064	                );
5065	                continue;
5066	            }
5067	            let side = self.resolve_admit_intent(intent);
5068	            self.admit_now(dtid, side);
5069	        }
5070	    }
