5081	    /// Check if a thread is alive, but removed from run queue.
5082	    fn thread_status(&self, dtid: DetTid) -> ThreadStatus {
5083	        if self.run_queue.contains_tid(dtid) {
5084	            ThreadStatus::Running
5085	        } else {
5086	            // Check all the places a blocked thread could be hiding.
5087	            // TODO: this O(N) search could be made more efficient with more indexing structures.
5088	            for v in self.blocked.futex_waiters.values() {
5089	                for waiter in v {
5090	                    if waiter.dettid == dtid {
5091	                        return ThreadStatus::NotRunning;
5092	                    }
5093	                }
5094	            }
5095	            for (_, evt) in self.blocked.timed_waiters.iter() {
5096	                match evt {
5097	                    TimedEvent::ThreadEvt(dt) => {
5098	                        if dt == dtid {
5099	                            return ThreadStatus::NotRunning;
5100	                        }
5101	                    }
5102	                    TimedEvent::SignalEvt(_, _, _) => {}
5103	                }
5104	            }
5105	            if self.blocked.external_io_blockers.contains_key(&dtid) {
5106	                return ThreadStatus::NotRunning;
5107	            }
5108	            if self.blocked.rt_sigsuspend_blockers.contains_key(&dtid)
5109	                || self.blocked.child_waiters.contains_key(&dtid)
5110	                || self
5111	                    .blocked
5112	                    .physical_child_waiters
5113	                    .values()
5114	                    .any(|waiters| waiters.contains(&dtid))
5115	            {
5116	                return ThreadStatus::NotRunning;
5117	            }
5118	            if self.pending_run_queue_admissions.contains_key(&dtid) {
5119	                return ThreadStatus::Running;
5120	            }
5121	            ThreadStatus::Gone
5122	        }
5123	    }
