        sched.reconnect_after_exec(ExecReconnect {
            caller,
            new_leader: leader,
            detpid,
            pre_exec_mm,
            post_exec_mm: pre_exec_mm.for_exec(detpid),
            child_tid_addr: 0,
            reconnect_priority: Some(DEFAULT_PRIORITY),
        })
    }

