6221	    #[derive(Debug, Clone, Copy)]
6222	    enum ExecReconnectTiming {
6223	        BeforeDaemon,
6224	        AfterCallerWait { yields: usize },
6225	        CallerResolvedBeforeReconnect,
6226	    }
