6228	    #[derive(Debug, PartialEq, Eq)]
6229	    struct ExecDrainObservation {
6230	        queue: Vec<DetTid>,
6231	        next_post_fork_draw: bool,
6232	        turn: u64,
6233	        old_leader_registration_survived: bool,
6234	    }
