6236	    async fn observe_exec_reconnect_drain(timing: ExecReconnectTiming) -> ExecDrainObservation {
6237	        let config = Config {
6238	            sched_seed: Some(0x5107),
6239	            runs_post_fork: RunsPostFork::Random,
6240	            cancel_killed_thread_rpcs: true,
6241	            ..Config::default()
6242	        };
6243	        let sched = Arc::new(Mutex::new(Scheduler::new(&config)));
6244	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
6245	        let leader = DetTid::from_raw(17);
6246	        let caller = DetTid::from_raw(18);
6247	        let lower = DetTid::from_raw(31);
6248	        let higher = DetTid::from_raw(37);
6249	        let barrier_parent = DetTid::from_raw(99);
6250	        let detpid = DetPid::from_raw(leader.as_raw());
6251	        let pre_exec_mm = MmId::initial(detpid);
6252	
6253	        let (caller_request, old_leader_request) = {
6254	            let mut s = sched.lock().unwrap();
6255	            s.thread_tree.add_child(leader, leader, true);
6256	            s.thread_tree.add_child(leader, caller, false);
6257	            register_known_thread(&mut s, leader);
6258	            register_known_thread(&mut s, caller);
6259	            // Give the destroyed leader a visibly different queue band. The
6260	            // replacement must use the caller's priority at the ordinary tail.
6261	            s.priorities.insert(leader, runqueue::FIRST_PRIORITY);
6262	            s.runqueue_push_back(leader);
6263	            s.runqueue_push_back(caller);
6264	            s.next_turns
6265	                .get(&leader)
6266	                .unwrap()
6267	                .req
6268	                .put(Ok(Resources::new(leader)));
6269	
6270	            register_known_thread(&mut s, lower);
6271	            register_known_thread(&mut s, higher);
6272	            s.admit_to_run_queue(lower, AdmitIntent::PostFork(RunsPostFork::Random));
6273	            s.admit_to_run_queue(higher, AdmitIntent::PostFork(RunsPostFork::Random));
6274	            // `step2` drains first, then this unresolved barrier returns
6275	            // `SkipTurn`, exposing the exact first-drain queue before step3 can
6276	            // tentatively select or rotate it.
6277	            s.vfork_barriers.insert(barrier_parent, None);
6278	            (
6279	                s.next_turns.get(&caller).unwrap().req.clone(),
6280	                s.next_turns.get(&leader).unwrap().req.clone(),
6281	            )
6282	        };
6283	
6284	        if matches!(timing, ExecReconnectTiming::BeforeDaemon) {
6285	            reconnect_nonleader_exec(
6286	                &mut sched.lock().unwrap(),
6287	                leader,
6288	                caller,
6289	                detpid,
6290	                pre_exec_mm,
6291	            );
6292	        } else if matches!(timing, ExecReconnectTiming::CallerResolvedBeforeReconnect) {
6293	            caller_request.put(Ok(Resources::new(caller)));
6294	        }
6295	
6296	        let turn_sched = sched.clone();
6297	        let turn_time = global_time.clone();
6298	        let turn = tokio::spawn(async move {
6299	            let last: Result<Resources, SkipTurn> = Err(SkipTurn);
6300	            do_a_turn_blocking(turn_sched, turn_time, &last).await
6301	        });
6302	
6303	        if let ExecReconnectTiming::AfterCallerWait { yields } = timing {
6304	            let mut saw_waiter = false;
6305	            for _ in 0..1_000 {
6306	                if caller_request.to_string() == "<ivar HasWaiter>" {
6307	                    saw_waiter = true;
6308	                    break;
6309	                }
6310	                tokio::task::yield_now().await;
6311	            }
6312	            assert!(saw_waiter, "daemon never waited on the exec caller request");
6313	            for _ in 0..yields {
6314	                tokio::task::yield_now().await;
6315	            }
6316	            reconnect_nonleader_exec(
6317	                &mut sched.lock().unwrap(),
6318	                leader,
6319	                caller,
6320	                detpid,
6321	                pre_exec_mm,
6322	            );
6323	        }
6324	
6325	        assert!(turn.await.expect("scheduler task panicked").is_err());
6326	        let mut s = sched.lock().unwrap();
6327	        let observation = ExecDrainObservation {
6328	            queue: s.run_queue.tids().copied().collect(),
6329	            next_post_fork_draw: s.child_runs_first_post_fork(RunsPostFork::Random),
6330	            turn: s.turn,
6331	            old_leader_registration_survived: s
6332	                .next_turns
6333	                .get(&leader)
6334	                .is_some_and(|turn| turn.req == old_leader_request),
6335	        };
6336	        if !matches!(timing, ExecReconnectTiming::CallerResolvedBeforeReconnect) {
6337	            assert_eq!(
6338	                observation
6339	                    .queue
6340	                    .iter()
6341	                    .filter(|tid| **tid == leader)
6342	                    .count(),
6343	                1
6344	            );
6345	            assert!(!observation.queue.contains(&caller));
6346	            assert!(!observation.old_leader_registration_survived);
6347	            assert!(s.pending_run_queue_admissions.is_empty());
6348	            assert!(s.pending_run_queue_removals.is_empty());
6349	        }
6350	        observation
6351	    }
