6373	    /// F6 (real-path regression): when the thread `step3_peek` tentatively
6374	    /// selected dies while the daemon awaits its request, `do_a_turn_blocking`
6375	    /// takes the `Err(ThreadExited)` fizzle arm. That arm MUST undo the tentative
6376	    /// pop so the selection does not outlive the turn; otherwise the next pass's
6377	    /// step2 removal drain calls `remove_tid` while `tentative_selection` is
6378	    /// still `Some`, tripping the run queue's transaction guard -- the "reconnect
6379	    /// panic moved one pass" defect (reachable in NORMAL async-DBT operation, not
6380	    /// just the reviewed edge case: any thread that exits during the await window
6381	    /// races here). This drives the ACTUAL async daemon function end to end
6382	    /// rather than poking `RunQueue` directly, which is the coverage gap the
6383	    /// pre-existing tests left. Positive control: after the fizzle the window is
6384	    /// closed and the following real step2 removal drain does not panic.
6385	    #[tokio::test]
6386	    async fn reconnect_fizzle_closes_window_so_next_removal_drain_is_safe() {
6387	        let config = Config::default();
6388	        let sched = Arc::new(Mutex::new(Scheduler::new(&config)));
6389	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
6390	        let dead = DetTid::from_raw(7);
6391	        {
6392	            let mut s = sched.lock().unwrap();
6393	            s.priorities.insert(dead, DEFAULT_PRIORITY);
6394	            s.next_turns.insert(
6395	                dead,
6396	                ThreadNextTurn {
6397	                    dettid: dead,
6398	                    child_tid_addr: 0,
6399	                    // Request already resolved to `ThreadExited`: the daemon will
6400	                    // observe the thread died the moment it awaits `req.get()`.
6401	                    req: Ivar::full(Err(ThreadExited)),
6402	                    resp: Ivar::new(),
6403	                    protocol: Default::default(),
6404	                },
6405	            );
6406	            s.runqueue_push_back(dead);
6407	        }
6408	        let last: Result<Resources, SkipTurn> = Err(SkipTurn);
6409	
6410	        // Pass 1: step1 sees a filled request (quiescent), step3 tentatively
6411	        // pops `dead`, then `req.get().await` yields `Err(ThreadExited)`. The
6412	        // fizzle arm returns `SkipTurn` and undoes the tentative pop.
6413	        let first = do_a_turn_blocking(sched.clone(), global_time.clone(), &last).await;
6414	        assert!(first.is_err(), "fizzled reconnect turn skips");
6415	        assert!(
6416	            !sched.lock().unwrap().run_queue.tentative_pop_in_progress(),
6417	            "the ThreadExited arm must undo the tentative pop"
6418	        );
6419	
6420	        // Pass 2: the dead thread's run-queue removal is now buffered, exactly
6421	        // as a reconnect/kill handler would leave it. Because pass 1 closed the
6422	        // window, the real step2 removal drain calls `remove_tid` with
6423	        // `tentative_selection == None` and does NOT trip the guard. Pre-fix
6424	        // (window left open) this call panicked.
6425	        {
6426	            let mut s = sched.lock().unwrap();
6427	            s.deschedule_or_defer(dead);
6428	            s.next_turns.remove(&dead);
6429	            let _ = s.step2_process_blocked(&global_time);
6430	            assert!(!s.run_queue.contains_tid(dead), "dead thread drained out");
6431	            assert!(s.pending_run_queue_removals.is_empty());
6432	        }
6433	    }
