6492	    /// F8 (non-committing fizzle must not advance virtual time): both sides of
6493	    /// the consequence, stated directly against `bump_global_time` -- the code
6494	    /// that turns a turn's returned `Result` into a virtual-time decision.
6495	    ///
6496	    /// The defect: the fizzle arm where `req.get()` resolved `Ok` but the
6497	    /// thread's `next_turns` entry vanished before the daemon re-acquired the
6498	    /// lock skips steps 4-7, commits nothing, and used to fall through to
6499	    /// `Ok(rsrcs)` -- landing in the advancing branch below and adding a
6500	    /// DETLOG-visible tick for work that never happened. It now reports
6501	    /// `Err(SkipTurn)` like its `ThreadExited` sibling, so this pair of
6502	    /// assertions is what that fix buys.
6503	    ///
6504	    /// Deliberately NOT an end-to-end test of that arm. Reaching it requires
6505	    /// teardown to clear `next_turns` inside the host-scheduling gap between the
6506	    /// await resolving and the re-lock, and that gap is not constructible from a
6507	    /// test: the daemon quiescence check only proceeds once every thread's request
6508	    /// is already filled, so `req.get()` never suspends and there is no window a
6509	    /// test can hold open. An attempt to win the lock in that gap is a genuine
6510	    /// race that would usually lose (and deadlocks outright on a current-thread
6511	    /// runtime, where the daemon's blocking `sched.lock()` stalls the whole
6512	    /// executor). F6's `reconnect_fizzle_closes_window_so_next_removal_drain_is_
6513	    /// safe` does drive the real `do_a_turn_blocking` for the sibling arm.
6514	    ///
6515	    /// NEGATIVE: a skipped turn leaves virtual time exactly where it was. That is
6516	    /// what the F8 fix buys; before it, the non-committing arm reported `Ok` and
6517	    /// landed in the advancing branch.
6518	    /// POSITIVE: a committed, non-internal turn *does* advance it. Without this
6519	    /// side the negative would pass vacuously for a `bump_global_time` that had
6520	    /// simply stopped advancing time at all.
6521	    #[test]
6522	    fn virtual_time_advances_for_a_committed_turn_and_not_for_a_skipped_one() {
6523	        let config = Config::default();
6524	        let runnable = DetTid::from_raw(13);
6525	
6526	        // A non-empty run queue keeps the "only waiting on external events"
6527	        // guard from suppressing the advance for an unrelated reason.
6528	        let mut advancing = Scheduler::new(&config);
6529	        advancing.priorities.insert(runnable, DEFAULT_PRIORITY);
6530	        advancing.runqueue_push_back(runnable);
6531	        let advancing_time = Mutex::new(GlobalTime::new(&config));
6532	        let before_commit = advancing_time.lock().unwrap().as_nanos();
6533	        advancing.bump_global_time(&advancing_time, &Ok(Resources::new(runnable)));
6534	        let after_commit = advancing_time.lock().unwrap().as_nanos();
6535	        assert!(
6536	            after_commit > before_commit,
6537	            "a committed turn must advance virtual time ({before_commit:?} -> {after_commit:?})"
6538	        );
6539	
6540	        let mut skipping = Scheduler::new(&config);
6541	        skipping.priorities.insert(runnable, DEFAULT_PRIORITY);
6542	        skipping.runqueue_push_back(runnable);
6543	        let skipping_time = Mutex::new(GlobalTime::new(&config));
6544	        let before_skip = skipping_time.lock().unwrap().as_nanos();
6545	        skipping.bump_global_time(&skipping_time, &Err(SkipTurn));
6546	        let after_skip = skipping_time.lock().unwrap().as_nanos();
6547	        assert_eq!(
6548	            after_skip, before_skip,
6549	            "a skipped turn must not advance virtual time"
6550	        );
6551	    }
