6578	    /// F7 (adjacent-snapshot sensitivity): this fixture directly places two
6579	    /// admissions in adjacent step2 drains; it does not model a production
6580	    /// handler protocol. Every current asynchronous admission site separately
6581	    /// fixes snapshot membership: ordinary clone buffers before the parent's
6582	    /// `ParentContinue`, `vfork` uses its registration barrier, and exec
6583	    /// reconnect buffers before retiring and resolving the caller request. See
6584	    /// [`Scheduler::admit_to_run_queue`] for those causal bindings.
6585	    ///
6586	    /// The synthetic split remains a negative/sensitivity bracket for that
6587	    /// requirement. Replaying one fixed split at one seed is reproducible, but
6588	    /// swapping which child occupies the first drain changes the resolved queue
6589	    /// order. Thus a future unanchored admission site would make host-selected
6590	    /// membership observable; this test must not be read as evidence that any
6591	    /// current production site is unanchored.
6592	    #[test]
6593	    fn deferred_admission_binds_to_snapshot_membership_across_adjacent_drains() {
6594	        let config = Config {
6595	            sched_seed: Some(0x5107),
6596	            runs_post_fork: RunsPostFork::Random,
6597	            ..Default::default()
6598	        };
6599	        let anchor = DetTid::from_raw(3);
6600	        let a = DetTid::from_raw(31);
6601	        let b = DetTid::from_raw(37);
6602	
6603	        // Admit `first` in drain 1 and `second` in drain 2 (two adjacent step2
6604	        // drains) and return the final run-queue order relative to a fixed
6605	        // anchor, which encodes each child's resolved front/back side.
6606	        let split = |first: DetTid, second: DetTid| -> Vec<DetTid> {
6607	            let mut sched = Scheduler::new(&config);
6608	            register_known_thread(&mut sched, anchor);
6609	            register_known_thread(&mut sched, a);
6610	            register_known_thread(&mut sched, b);
6611	            sched.runqueue_push_back(anchor);
6612	
6613	            sched.admit_to_run_queue(first, AdmitIntent::PostFork(RunsPostFork::Random));
6614	            sched.drain_pending_run_queue_admissions(); // drain 1
6615	            sched.admit_to_run_queue(second, AdmitIntent::PostFork(RunsPostFork::Random));
6616	            sched.drain_pending_run_queue_admissions(); // drain 2 (adjacent)
6617	
6618	            sched.run_queue.tids().copied().collect()
6619	        };
6620	
6621	        // Fixed synthetic membership is deterministic across identical replays.
6622	        let canonical = split(a, b);
6623	        assert_eq!(
6624	            canonical,
6625	            split(a, b),
6626	            "identical schedule -> identical result"
6627	        );
6628	        assert!(canonical.contains(&a) && canonical.contains(&b) && canonical.contains(&anchor));
6629	
6630	        // Sensitivity control: changing synthetic snapshot membership changes
6631	        // the outcome for this seed, so a missing production anchor would be
6632	        // observable rather than inert.
6633	        assert_ne!(
6634	            split(a, b),
6635	            split(b, a),
6636	            "swapping snapshot membership changes the resolved order"
6637	        );
6638	    }
