6682	        // BEFORE the child registers. An unfulfilled barrier at continuation must be kept, not
6683	        // torn down as a failed clone; otherwise the late child panics on registration.
6684	        let config = Config {
6685	            backend_defers_vfork_child_registration: true,
6686	            ..Config::default()
6687	        };
6688	        let mut scheduler = Scheduler::new(&config);
