6691	        let op_id = ExternalOpId::new(parent, 7);
6692	        let mut continuation = Resources::new(parent);
6693	        continuation.insert(ResourceID::BlockedExternalContinue(op_id), Permission::RW);
6694	
6695	        scheduler.vfork_barriers.insert(parent, None);
6696	        scheduler.next_turns.insert(
6697	            parent,
6698	            ThreadNextTurn {
6699	                dettid: parent,
6700	                child_tid_addr: 0,
6701	                req: Ivar::full(Ok(continuation)),
6702	                resp: Ivar::new(),
6703	                protocol: Default::default(),
6704	            },
6705	        );
