6707	        // Parent is at its continuation but the child has not registered: keep waiting, keep the
6708	        // barrier (the failed-clone teardown must NOT fire on a deferring backend).
6709	        assert!(scheduler.step2a_wait_for_vfork_barrier().is_err());
6710	        assert_eq!(scheduler.vfork_barriers.get(&parent), Some(&None));
