    reconnect_nonleader_exec(&mut sched, leader, caller, detpid, pre_exec_mm);

    assert!(sched.run_queue.tentative_pop_in_progress());
    assert_eq!(
        sched.run_queue.tids().copied().collect::<Vec<_>>(),
        queue_during_window,
