7588	    fn physical_wait_handoff_queue(completion_before_wait: bool) -> Vec<DetTid> {
7589	        let config = Config {
7590	            backend_reports_physical_process_exits: true,
7591	            ..Config::default()
7592	        };
7593	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
7594	        let mut scheduler = Scheduler::new(&config);
7595	        let waiter = DetTid::from_raw(100);
7596	        let sibling = DetTid::from_raw(200);
7597	        let child = DetPid::from_raw(300);
7598	        register_known_thread(&mut scheduler, waiter);
7599	        register_known_thread(&mut scheduler, sibling);
7600	        scheduler.runqueue_push_back(waiter);
7601	        scheduler.runqueue_push_back(sibling);
7602	
7603	        assert!(scheduler.begin_physical_process_exit(child));
7604	        if completion_before_wait {
7605	            assert!(scheduler.complete_physical_process_exit(child));
7606	        }
7607	
7608	        assert_eq!(scheduler.run_queue.tentative_pop_tid(waiter), Some(waiter));
7609	        assert!(
7610	            scheduler
7611	                .block_for_one_resource(
7612	                    waiter,
7613	                    &ResourceID::WaitPhysicalChild(child),
7614	                    &Permission::W,
7615	                    None,
7616	                    &Ivar::new(),
7617	                )
7618	                .is_err()
7619	        );
7620	        assert_eq!(
7621	            scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
7622	            vec![sibling]
7623	        );
7624	
7625	        if !completion_before_wait {
7626	            assert!(
7627	                scheduler.step2_process_blocked(&global_time).is_err(),
7628	                "a runnable sibling must not pass the pending physical-exit barrier"
7629	            );
7630	            assert_eq!(
7631	                scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
7632	                vec![sibling]
7633	            );
7634	            assert!(scheduler.complete_physical_process_exit(child));
7635	        }
7636	
7637	        assert!(scheduler.step2_process_blocked(&global_time).is_ok());
7638	        assert!(scheduler.pending_run_queue_admissions.is_empty());
7639	        assert!(scheduler.blocked.physical_child_ready.contains(&waiter));
7640	        scheduler.run_queue.tids().copied().collect()
7641	    }
