7796	    /// Populate a scheduler with a deadlock's worth of blocked state, inserting
7797	    /// each collection in the caller's chosen order.
7798	    ///
7799	    /// `reverse` exists so the same logical state can be built two ways: the
7800	    /// report must not depend on insertion order, because `futex_waiters` is a
7801	    /// `HashMap`, `timed_out_futex_waiters` a `HashSet`, and
7802	    /// `Resources::resources` a `HashMap`.
7803	    fn deadlocked_scheduler(config: &Config, reverse: bool) -> Scheduler {
7804	        let mut scheduler = Scheduler::new(config);
7805	        let mm = MmId::initial(DetTid::from_raw(3));
7806	        let mut futexes = vec![
7807	            (FutexID::private(mm, 0x404100), 5),
7808	            (FutexID::private(mm, 0x404200), 7),
7809	            (FutexID::private(mm, 0x404300), 9),
7810	        ];
7811	        let mut tids = vec![3, 5, 7, 9];
7812	        if reverse {
7813	            futexes.reverse();
7814	            tids.reverse();
7815	        }
7816	
7817	        for (futex_id, dettid) in futexes {
7818	            scheduler
7819	                .blocked
7820	                .futex_waiters
7821	                .entry(futex_id)
7822	                .or_default()
7823	                .push(futex_waiter(dettid, u32::MAX));
7824	        }
7825	        for dettid in tids {
7826	            let dettid = DetTid::from_raw(dettid);
7827	            // A request carrying several resources: `Resources::resources` is a
7828	            // HashMap, so an unsorted render would vary here too.
7829	            let mut resources = Resources::new(dettid);
7830	            resources.insert(ResourceID::FutexWait, Permission::R);
7831	            resources.insert(ResourceID::MemAddrSpace(dettid), Permission::RW);
7832	            scheduler.next_turns.insert(
7833	                dettid,
7834	                ThreadNextTurn {
7835	                    dettid,
7836	                    child_tid_addr: 0,
7837	                    // A FULL ivar: `Debug` on this prints the parked waker's raw
7838	                    // host pointers, which is exactly what must not reach stderr.
7839	                    req: Ivar::full(Ok(resources)),
7840	                    resp: Ivar::new(),
7841	                    protocol: Default::default(),
7842	                },
7843	            );
7844	            scheduler.blocked.timed_out_futex_waiters.insert(dettid);
7845	        }
7846	        scheduler
7847	            .blocked
7848	            .timed_waiters
7849	            .insert(LogicalTime::INDEFINITE, DetTid::from_raw(11));
7850	        scheduler
7851	    }
