7853	    /// The deadlock report reaches stderr, so it must be byte-identical across
7854	    /// runs of the same program. Codex measured the unguarded `{:?}` dump
7855	    /// emitting `Waker { data: 0x557e90a74680, .. }` in one run and
7856	    /// `Waker { data: 0x5654e2b08680, .. }` in the next: raw host pointers that
7857	    /// move with ASLR. Assert the render carries no host pointer and no
7858	    /// insertion-order dependence.
7859	    #[test]
7860	    fn deadlock_report_is_deterministic_and_carries_no_host_pointer() {
7861	        let config = Config::default();
7862	        let forward = deadlocked_scheduler(&config, false).format_terminal_deadlock();
7863	        let reversed = deadlocked_scheduler(&config, true).format_terminal_deadlock();
7864	
7865	        // Same logical state built in two insertion orders must render
7866	        // identically: no HashMap/HashSet iteration order may leak.
7867	        assert_eq!(forward, reversed);
7868	
7869	        // No `Debug` of an Ivar/Waker, and so no host pointer.
7870	        //
7871	        // ⚠️ THIS LIST CANNOT SEE A SECTION THE FIXTURE NEVER RENDERS. It only
7872	        // inspects the text `deadlocked_scheduler` happens to produce. When you
7873	        // add a section to `format_terminal_deadlock`, add the state that triggers
7874	        // it to the fixture in the same change, or this test will pass and say
7875	        // nothing about your section.
7876	        //
7877	        // These tokens catch host POINTERS and raw thread ids. The subtler failure
7878	        // is a host-influenced COUNTER, which looks like an ordinary small integer
7879	        // and matches no banned word -- which is why the byte-identical assertion
7880	        // above is the load-bearing check and this list is only a backstop.
7881	        for banned in [
7882	            "Waker", "Ivar", "vtable", "Mutex", "poisoned", "ThreadId", "0x7f",
7883	        ] {
7884	            assert!(
7885	                !forward.contains(banned),
7886	                "deadlock report leaked {banned:?}; it must print only guest-level \
7887	                 identities.\n{forward}"
7888	            );
7889	        }
7890	
7891	        // The report is still substantive: it names every blocked thread, the
7892	        // futex keys, and the indefinite deadline.
7893	        for expected in [
7894	            // This fixture holds BOTH pools, so the state-derived headline must
7895	            // name both rather than whichever branch happened to fire.
7896	            "Deadlock detected: thread(s) waiting on futex, and thread(s) waiting \
7897	             indefinitely (pause, or a timer beyond the end of logical time), but no \
7898	             runnable threads left.",
7899	            "dtid 3",
7900	            "dtid 9",
7901	            "0x404100",
7902	            "0x404300",
7903	            "INDEFINITE (no deadline)",
7904	            "FutexWait: R, MemAddrSpace(DetPid(3)): RW",
7905	        ] {
7906	            assert!(
7907	                forward.contains(expected),
7908	                "deadlock report lost {expected:?}:\n{forward}"
7909	            );
7910	        }
7911	    }
