    // retaining a guest mapping for the duration of a blocking host wait.
    let timeout = if args[3] != 0
        && matches!(
            command,
            FUTEX_WAIT | FUTEX_LOCK_PI | FUTEX_WAIT_BITSET | FUTEX_WAIT_REQUEUE_PI | FUTEX_LOCK_PI2
        ) {
        let timeout = match read_guest_struct::<libc::timespec>(memory, args[3]) {
            Ok(timeout) => timeout,
            Err(error) => return error,
        };
        if timeout.tv_sec < 0 || !(0..1_000_000_000).contains(&timeout.tv_nsec) {
            return negative_errno(libc::EINVAL);
        }
        Some(timeout)
    } else {
        None
    };

    // do_futex rejects unsupported commands and clock-flag combinations
    // before get_futex_key inspects either word.
    if operation & FUTEX_CLOCK_REALTIME != 0
        && !matches!(
            command,
            FUTEX_WAIT_BITSET | FUTEX_WAIT_REQUEUE_PI | FUTEX_LOCK_PI2
        )
    {
        return negative_errno(libc::ENOSYS);
    }
    if !matches!(
        command,
        FUTEX_WAIT
            | FUTEX_WAKE
            | FUTEX_REQUEUE
            | FUTEX_CMP_REQUEUE
            | FUTEX_WAKE_OP
            | FUTEX_LOCK_PI
            | FUTEX_UNLOCK_PI
            | FUTEX_TRYLOCK_PI
            | FUTEX_WAIT_BITSET
            | FUTEX_WAKE_BITSET
            | FUTEX_WAIT_REQUEUE_PI
            | FUTEX_CMP_REQUEUE_PI
            | FUTEX_LOCK_PI2
    ) {
        return negative_errno(libc::ENOSYS);
    }

    // These non-PI handlers enter get_futex_key before any error with a
    // different errno, and key lookup rejects natural-alignment violations
    // before inspecting the word. PI handlers have earlier configuration,
    // allocation, ownership, or second-word work, so retain their existing
    // adapter ordering. Host placement must not decide the covered cases.
    if matches!(
        command,
        FUTEX_WAIT
            | FUTEX_WAKE
            | FUTEX_REQUEUE
            | FUTEX_CMP_REQUEUE
            | FUTEX_WAKE_OP
            | FUTEX_WAIT_BITSET
            | FUTEX_WAKE_BITSET
    ) && !args[0].is_multiple_of(std::mem::size_of::<u32>() as u64)
    {
        return negative_errno(libc::EINVAL);
    }
    let Ok(uaddr) = guest_host_address(memory, args[0], std::mem::size_of::<u32>()) else {
        return negative_errno(libc::EFAULT);
    };

    let mut second_operand = None;
    let fourth = timeout
        .as_ref()
        .map_or(args[3] as usize, |value| std::ptr::from_ref(value) as usize);
    let uaddr2 = if matches!(
        command,
        FUTEX_REQUEUE
            | FUTEX_CMP_REQUEUE
            | FUTEX_WAKE_OP
            | FUTEX_WAIT_REQUEUE_PI
            | FUTEX_CMP_REQUEUE_PI
    ) {
        if matches!(command, FUTEX_REQUEUE | FUTEX_CMP_REQUEUE | FUTEX_WAKE_OP)
            && !args[4].is_multiple_of(std::mem::size_of::<u32>() as u64)
        {
            return negative_errno(libc::EINVAL);
        }
        match guest_host_address(memory, args[4], std::mem::size_of::<u32>()) {
            Ok(operand) => {
                let address = operand.address();
                second_operand = Some(operand);
                address
            }
            Err(error) => return error,
        }
    } else {
        0
    };

    // SAFETY: translated pointers remain within the shared guest mapping for
    // the duration of the syscall. The host kernel performs the atomic futex
    // operation against the same bytes mapped by every guest-thread VM.
    let result = unsafe {
        libc::syscall(
            libc::SYS_futex,
            uaddr.address(),
            operation,
            args[2] as u32,
            fourth,
            uaddr2,
            args[5] as u32,
        )
    };
    let result = if result < 0 {
        io_error(std::io::Error::last_os_error())
    } else {
        result as i64
    };
    drop((uaddr, second_operand));
    result
}

// AUTONOMOUS-BOT-IMPLEMENTED
// TODO-HUMAN-REVIEW(PR-232): Review task-local robust-list registration.
fn set_robust_list(state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    if args[1] != ROBUST_LIST_HEAD_SIZE {
        return negative_errno(libc::EINVAL);
    }
    let updated = state
        .task_lifecycle
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .set_robust_list(state.tid, args[0]);
    debug_assert!(
        updated,
        "current KVM task is absent from its lifecycle table"
    );
    if !updated {
        return negative_errno(libc::ESRCH);
    }
    0
}

// AUTONOMOUS-BOT-IMPLEMENTED
// TODO-HUMAN-REVIEW(PR-232): Review process-tree robust-list queries.
fn get_robust_list(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let requested = match args[0] as libc::pid_t {
        0 => state.tid,
        tid => tid,
    };
    let Some(target) = state
        .task_lifecycle
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(requested)
    else {
        return negative_errno(libc::ESRCH);
    };

    // Every task has the fixed virtual-root credentials. Match the remaining
    // ptrace access predicates: same-thread-group reads are always allowed;
    // cross-process reads require either a dumpable target or CAP_SYS_PTRACE.
    if target.tgid != state.pid
        && !target.dumpable
        && state.capability_effective & (1_u64 << CAP_SYS_PTRACE) == 0
    {
        return negative_errno(libc::EPERM);
    }

    // Linux resolves and authorizes the target first, then writes the fixed
    // header size before the head pointer. Preserve that partial-copy ordering.
    if args[2] == 0 || write_u64(memory, args[2], ROBUST_LIST_HEAD_SIZE) != 0 {
        return negative_errno(libc::EFAULT);
    }
    if args[1] == 0 || write_u64(memory, args[1], target.robust_list_head) != 0 {
        return negative_errno(libc::EFAULT);
    }
    0
}

fn guest_host_address(
    memory: &GuestMemory,
    guest_address: u64,
    length: usize,
) -> Result<HostMemoryOperand, i64> {
    memory
        .user()
        .host_operand(guest_address, length)
        .map_err(|_| negative_errno(libc::EFAULT))
}

/// A [`crate::SyscallExecutor`] that supplies the static-ELF guest-kernel semantics
/// ([`execute_basic_syscall`]) to the tool-driven run loop
/// ([`crate::KvmBackend::run_static_elf_with_tool`]).
///
/// `execute` returns the raw syscall result and records, as side effects for
/// the run loop to apply after the tool handler completes, any pending FS/GS
/// base update (from `arch_prctl`) and the exit code (from `exit`/`exit_group`).
/// This lets a Reverie tool's `tail_inject` drive the same guest-kernel that
/// [`crate::KvmBackend::run_static_elf`] uses directly.
pub(crate) struct ElfExecutor {
    state: LoadedStaticElf,
    task_generation: u64,
    process_generation: u64,
    signal_registry: Arc<ProcessSignalRegistry>,
    signal_binding: Arc<ProcessBinding>,
    // Retained view only; allocation/policy authority lives in its one owner.
    address_space: Option<GuestMemory>,
    file_table: Arc<std::sync::Mutex<FileTableState>>,
    output: Option<CapturedOutput>,
    owns_output: bool,
    next_pid: Arc<AtomicI32>,
    sigchld_auto_reap: Arc<AtomicBool>,
    // TODO-HUMAN-REVIEW(PR-235): Review concurrent KVM process lifecycle ownership.
    pending_processes: std::collections::BTreeMap<i32, PendingProcess>,
    completed_processes: Vec<ChildProcessHandle>,
    // Failed host spawns still own constructed child Tool state. Retain its
    // consuming cleanup without polling inside the parent's borrowed callback.
    // Mutex makes the executor Sync while each owned future only needs Send.
    unstarted_tool_cleanup: Mutex<Vec<UnstartedToolCleanup>>,
    // Exiting workers transfer forks to their process owner before returning.
    transferred_processes: Arc<Mutex<std::collections::BTreeMap<i32, Vec<OwnedChildProcesses>>>>,
    child_completion_sender: std::sync::mpsc::Sender<i32>,
    child_completion_receiver: Mutex<std::sync::mpsc::Receiver<i32>>,
    process_action: Option<ProcessAction>,
    pending_segment: Option<(SegmentBase, u64)>,
    current_user_stack_pointer: Option<u64>,
    exit_status: Option<ExitStatus>,
    exit_group: bool,
    clear_child_tid: Option<u64>,
    signal_callback_nonce: u64,
    parked_signals: Option<ParkedSignalState>,
    completed_signal_effects: Vec<reverie::SignalDequeue>,
    signal_effect_raw_result: Option<i64>,
}

/// Keeps one exact process-generation registry binding alive without exposing
/// its backend-private representation.
pub(crate) struct ProcessSignalBindingGuard {
    _binding: Arc<ProcessBinding>,
}

pub(crate) type UnstartedToolCleanup =
    Pin<Box<dyn Future<Output = crate::Result<()>> + Send + 'static>>;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ChildStartCommand {
    Start,
    Cancel,
    /// Consuming cleanup after the run's terminal transition, not an ordinary
    /// successful cancellation or permission to execute the child.
    CancelAfterFailure,
}

impl ChildStartCommand {
    pub(crate) fn failure(self) -> Option<crate::Error> {
        matches!(self, Self::CancelAfterFailure).then_some(crate::Error::RunAborted)
    }
}

#[derive(Clone)]
pub(crate) struct ChildStartGate {
    state: Arc<Mutex<ChildStartGateState>>,
}

